pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
    ensures always(p.and(q)) == always(p).and(always(q)),
{
    // Prove mutual entailment and then use extensional equality of TempPred.

    // 1. always(p.and(q)) entails always(p).and(always(q))
    assert(always(p.and(q)).entails(always(p).and(always(q))));
    {
        assert(
            forall |ex: Execution<T>|
                always(p.and(q)).satisfied_by(ex)
                    ==> always(p).and(always(q)).satisfied_by(ex)
        );
    }

    // 2. always(p).and(always(q)) entails always(p.and(q))
    assert(always(p).and(always(q)).entails(always(p.and(q))));
    {
        assert(
            forall |ex: Execution<T>|
                always(p).and(always(q)).satisfied_by(ex)
                    ==> always(p.and(q)).satisfied_by(ex)
        );
    }

    // Conclude equality from the entailments.
    temp_pred_equality(always(p.and(q)), always(p).and(always(q)));
}

