pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
    ensures always(p.and(q)) == always(p).and(always(q)),
{
    // We'll show mutual entailment between the two TempPreds, and then use
    // `temp_pred_equality` to conclude equality.

    let lp = always(p.and(q));
    let rp = always(p).and(always(q));

    // Prove: lp.entails(rp)
    {
        // Unfold the definition of `entails`: valid(lp.implies(rp))
        // which is: forall ex, lp.satisfied_by(ex) ==> rp.satisfied_by(ex)
        assert(
            forall |ex: Execution<T>| 
                lp.satisfied_by(ex) ==> rp.satisfied_by(ex)
        );
        assert(lp.entails(rp));
    }

    // Prove: rp.entails(lp)
    {
        assert(
            forall |ex: Execution<T>| 
                rp.satisfied_by(ex) ==> lp.satisfied_by(ex)
        );
        assert(rp.entails(lp));
    }

    temp_pred_equality(lp, rp);
}

