    // Prove mutual entailment between lp and rp.
    //
    // Unfolding the definitions:
    //   lp.satisfied_by(ex)  = forall i, (p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i)))
    //   rp.satisfied_by(ex)  = (forall i, p.satisfied_by(ex.suffix(i))) && (forall i, q.satisfied_by(ex.suffix(i)))

    // lp.entails(rp)
    assert(
        forall |ex: Execution<T>| 
            lp.satisfied_by(ex) ==> rp.satisfied_by(ex)
    ) by {
        forall |ex: Execution<T>| {
            if lp.satisfied_by(ex) {
                // Prove always(p).satisfied_by(ex)
                assert(
                    forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i))
                ) by {
                    forall |i: nat| {
                        // From lp we know (p && q) holds at each suffix.
                        assert((p.and(q)).satisfied_by(ex.suffix(i)));
                        assert(p.satisfied_by(ex.suffix(i)));
                    }
                };

                assert(always(p).satisfied_by(ex));

                // Prove always(q).satisfied_by(ex)
                assert(
                    forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i))
                ) by {
                    forall |i: nat| {
                        assert((p.and(q)).satisfied_by(ex.suffix(i)));
                        assert(q.satisfied_by(ex.suffix(i)));
                    }
                };

                assert(always(q).satisfied_by(ex));

                // Combine
                assert(rp.satisfied_by(ex));
            }
        }
    };
    assert(lp.entails(rp));

    // rp.entails(lp)
    assert(
        forall |ex: Execution<T>| 
            rp.satisfied_by(ex) ==> lp.satisfied_by(ex)
    ) by {
        forall |ex: Execution<T>| {
            if rp.satisfied_by(ex) {
                // From rp we get both always(p) and always(q).
                assert(always(p).satisfied_by(ex));
                assert(always(q).satisfied_by(ex));

                // Hence (p && q) holds at every suffix position.
                assert(
                    forall |i: nat| #[trigger]
                        (p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i)))
                ) by {
                    forall |i: nat| {
                        assert(p.satisfied_by(ex.suffix(i)));
                        assert(q.satisfied_by(ex.suffix(i)));
                    }
                };

                assert(lp.satisfied_by(ex));
            }
        }
    };
    assert(rp.entails(lp));

    temp_pred_equality(lp, rp);
}

