pub proof fn always_and_satisfied_by<T>(p: TempPred<T>, q: TempPred<T>, ex: Execution<T>)
    ensures always(p.and(q)).satisfied_by(ex) == always(p).and(always(q)).satisfied_by(ex),
{
    // Unfold the definitions to a pure logical equivalence:
    // forall i, (p(i) && q(i))  <==>  (forall i p(i)) && (forall i q(i))
    assert(
        (forall |i: nat| #[trigger] (p.and(q)).satisfied_by(ex.suffix(i)))
            <==>
        ((forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i)))
            &&
         (forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i))))
    );

    // Now rewrite both sides using the definition of `always` and `and`.
    assert(always(p.and(q)).satisfied_by(ex)
        <==>
        (forall |i: nat| #[trigger] (p.and(q)).satisfied_by(ex.suffix(i))));

    assert(always(p).and(always(q)).satisfied_by(ex)
        ==
        (always(p).satisfied_by(ex) && always(q).satisfied_by(ex)));

    // Combine the equalities.
    assert(always(p.and(q)).satisfied_by(ex)
        == always(p).and(always(q)).satisfied_by(ex));
}

pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
    ensures always(p.and(q)) == always(p).and(always(q)),
{
    let lp = always(p.and(q));
    let rp = always(p).and(always(q));

    // For any execution, their `satisfied_by` predicates are equal.
    assert(
        forall |ex: Execution<T>| #[trigger] lp.satisfied_by(ex) <==> rp.satisfied_by(ex)
    ) by {
        forall |ex: Execution<T>| {
            always_and_satisfied_by(p, q, ex);
        }
    };

    // Hence they entail each other.
    assert(forall |ex: Execution<T>| #[trigger] lp.satisfied_by(ex) ==> rp.satisfied_by(ex));
    assert(forall |ex: Execution<T>| #[trigger] rp.satisfied_by(ex) ==> lp.satisfied_by(ex));

    temp_pred_equality(lp, rp);
}

